def compute(vars):
    translation = vars["v1"]
    unrealized_loss = vars["v2"]
    loss_magnitude = -unrealized_loss

    if loss_magnitude == 0:
        return None

    offset_percentage = translation / loss_magnitude * 100

    return {
        "value": offset_percentage,
        "trace": {
            "translation": translation,
            "unrealized_loss": unrealized_loss,
            "loss_magnitude": loss_magnitude,
            "offset_percentage": offset_percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
